Subroutine Suspendable Saludar(nombre As String)
  Write "Hola, ", nombre;
EndSubroutine

Algorithm Orden
  Tasks
    Spawn Saludar("Ana");
    Spawn Saludar("Leo");
    Write "lanzadas";
  EndTasks
  Write "todas terminaron";
EndAlgorithm

Subroutine Suspendable Cuadrado(n As Integer) As Integer
  Return n * n;
EndSubroutine

Algorithm Paralelo
  Tasks
    Define a As Task<Integer> <- Spawn Cuadrado(3);
    Define b As Task<Integer> <- Spawn Cuadrado(4);
    Write Await a + Await b;
  EndTasks
EndAlgorithm

Subroutine Suspendable Dividir(a As Integer, b As Integer) As Result<Integer, String>
  If b = 0 Then
    Return Failure("división entre cero");
  EndIf
  Return Success(a Div b);
EndSubroutine

Algorithm Fallos
  Tasks fallo
    Spawn Dividir(10, 2);
    Spawn Dividir(1, 0);
  EndTasks
  Switch fallo Do
    Some(f):
      Write "primer error: ", f.first;
    None:
      Write "todo bien";
  EndSwitch
EndAlgorithm
